mapper.select:
SELECT * FROM logan_device_command
WHERE app_id = #{appId} AND device_id = #{deviceId} AND status = "pending"
  AND expire_time > #{now}
ORDER BY id ASC
LIMIT #{limit}

mapper.update:
UPDATE logan_device_command SET status = #{status}, ack_time = #{now}
, result_note = #{resultNote}
WHERE id = #{id} AND status IN ("pending","delivered")

mapper.select:
SELECT * FROM logan_device_command

    AND app_id = #{appId}
    AND device_id = #{deviceId}

ORDER BY id DESC
LIMIT #{limit}
